/**
 * Fixtures for web/tests/frontend-phase-probe.mjs (frontend UI probe only).
 *
 * Owned by this probe: every value here is generated by the probe or read from
 * the owned launcher's `owner.json` (random test credentials written by
 * product-readiness-db.go). Nothing reads production passwords, real tokens,
 * private keys or deployed configuration.
 *
 * The "node" fixture is a SYNTHETIC native configuration used to prove
 * rename-only edits are lossless. It is NOT a working core config and must not
 * be described as real core/Agent acceptance.
 */

export const SYNTHETIC_NODE_NAME = 'PR probe synthetic node (NOT a real core config)'
export const SYNTHETIC_NODE_RENAMED = 'PR probe renamed node (rename only)'

/** Native config with deep unknown-but-valid keys, to detect silent loss on rename. */
export const SYNTHETIC_NODE_WRITE = (serverId) => ({
  name: SYNTHETIC_NODE_NAME,
  server_id: serverId,
  host: 'fixture.invalid',
  port: 24443,
  external_port: 443,
  listen: '127.0.0.1',
  protocol: 'vless',
  enabled: true,
  sort_order: 7,
  stream_settings: {
    network: 'ws',
    security: 'none',
    wsSettings: { path: '/SYNTHETIC-probe', headers: { 'X-Probe-Only': 'SYNTHETIC' } },
    sockopt: { tcpNoDelay: true, tcpKeepAliveIdle: 60 },
  },
  protocol_settings: { decryption: 'none', syntheticProbeKey: 'SYNTHETIC-not-real-core' },
  client_settings: { syntheticClientKey: 'SYNTHETIC-client-not-delivered' },
})

/** Fields a rename-only save must not touch (name/version/updated_at excluded). */
export const INVARIANT_NODE_FIELDS = [
  'server_id', 'host', 'port', 'external_port', 'listen', 'protocol', 'enabled',
  'sort_order', 'stream_settings', 'protocol_settings', 'client_settings', 'server_key_set',
]

/**
 * Compare two node records and return the list of invariant fields that
 * changed. Empty array = rename was lossless.
 */
export function changedInvariantFields(before, after, fields = INVARIANT_NODE_FIELDS) {
  const changed = []
  for (const field of fields) {
    const a = JSON.stringify(before?.[field] ?? null)
    const b = JSON.stringify(after?.[field] ?? null)
    if (a !== b) changed.push(field)
  }
  return changed
}

/** Read-only view of a subscription record: token is never persisted to evidence. */
export function maskedSubscription(record) {
  if (!record) return null
  return { ...record, token: record.token ? '[REDACTED]' : null, url: record.url ? '[REDACTED-url]' : null }
}
